#include "SoraCatalog.h"
#include "SoraCatalogJson.h"
#include "SoraStealthRules.h"

// A chapter's space block, generated by scripts/unreal/campaign_space.py and
// checked host-side by validate_campaign.py. The loader refuses any missing
// or mistyped field, a point count that disagrees with the beat's task, an
// escort whose path is not its road, and a horse SoraMountRules rejects.
namespace
{
using namespace SoraCatalogJson;

bool SpaceNumber(const TSharedPtr<FJsonValue>& Value, double& Out)
{
    int32 Whole32 = 0;
    return Value.IsValid() && Value->TryGetNumber(Out) && Whole(Out, Whole32);
}
// [x, y] or [x, y, z] of whole centimetres (or degrees).
bool SpaceVector(const TSharedPtr<FJsonValue>& Value, int32 Count, double* Out)
{
    const FJsonRows* Parts = nullptr;
    if (!Value.IsValid() || !Value->TryGetArray(Parts) || !Parts || Parts->Num() != Count) return false;
    for (int32 Index = 0; Index < Count; ++Index)
        if (!SpaceNumber((*Parts)[Index], Out[Index])) return false;
    return true;
}
bool SpacePoint(const TSharedPtr<FJsonValue>& Value, FVector2D& Out)
{
    double Parts[2] = {};
    if (!SpaceVector(Value, 2, Parts)) return false;
    Out = FVector2D(Parts[0], Parts[1]);
    return true;
}
bool SpacePose(const FJsonObject& Object, const TCHAR* Key, FVector2D& Location, float& Yaw)
{
    double Parts[3] = {};
    if (!SpaceVector(Object.TryGetField(Key), 3, Parts)) return false;
    Location = FVector2D(Parts[0], Parts[1]); Yaw = static_cast<float>(Parts[2]);
    return true;
}
bool SpacePoints(const FJsonRows* Values, TArray<FVector2D>& Out)
{
    if (!Values) return false;
    for (const auto& Value : *Values)
    {
        FVector2D Point;
        if (!SpacePoint(Value, Point)) return false;
        Out.Add(Point);
    }
    return true;
}
bool SpaceBoxes(const FJsonRows* Values, TArray<FSoraBox>& Out)
{
    if (!Values) return false;
    for (const auto& Value : *Values)
    {
        double Parts[5] = {};
        if (!SpaceVector(Value, 5, Parts) || Parts[2] <= 0 || Parts[3] <= 0 || Parts[4] <= 0) return false;
        Out.Add({FVector2D(Parts[0], Parts[1]), FVector2D(Parts[2], Parts[3]), static_cast<float>(Parts[4])});
    }
    return true;
}
bool SpaceVolume(const FJsonObject& Object, FSoraVolume& Out, bool bNamed)
{
    return (!bNamed || (Str(Object, TEXT("event"), Out.Event) && Out.Event.StartsWith(TEXT("volume_enter:")))) &&
        SpacePoint(Object.TryGetField(TEXT("center")), Out.Center) && SpacePoint(Object.TryGetField(TEXT("size")), Out.Size) &&
        Out.Size.X > 0 && Out.Size.Y > 0;
}
bool SpaceNames(const FJsonRows* Values, TArray<FName>& Out)
{
    TArray<FString> Names;
    if (!Strings(Values, Names)) return false;
    for (const FString& Name : Names) Out.Add(FName(*Name));
    return true;
}
bool SpaceNullableName(const FJsonObject& Object, const TCHAR* Key, FName& Out)
{
    FString Name;
    if (!Nullable(Object, Key, Name)) return false;
    Out = Name.IsEmpty() ? NAME_None : FName(*Name);
    return true;
}
bool SpaceGait(const FString& Name, SoraMountRules::EGait& Out)
{
    static const TMap<FString, SoraMountRules::EGait> Gaits = {
        {TEXT("walk"), SoraMountRules::EGait::Walk}, {TEXT("trot"), SoraMountRules::EGait::Trot},
        {TEXT("canter"), SoraMountRules::EGait::Canter}, {TEXT("gallop"), SoraMountRules::EGait::Gallop}};
    const SoraMountRules::EGait* Found = Gaits.Find(Name);
    if (Found) Out = *Found;
    return Found != nullptr;
}
// The horse under the hero: gaits, wind, fear, arcs and what goes with her.
bool SpaceReadMount(const FJsonObject& O, const SoraBeatRules::FTask& Task, FSoraMount& M)
{
    using namespace SoraMountRules;
    FString Horse, Coat;
    TArray<FString> Gaits;
    const TSharedPtr<FJsonObject> Stamina = Child(O, TEXT("stamina"));
    const TSharedPtr<FJsonObject> Arcs = Child(O, TEXT("arcs"));
    const FJsonRows* Speeds = Rows(O, TEXT("speeds_cm_s"));
    const FJsonRows* Wind = Stamina ? Rows(*Stamina, TEXT("per_s")) : nullptr;
    int32 Max = 0;
    double Place[3] = {};
    if (!Str(O, TEXT("horse"), Horse) || !Str(O, TEXT("coat"), Coat) || !O.TryGetBoolField(TEXT("mounted"), M.bMounted) ||
        !Strings(Rows(O, TEXT("gaits")), Gaits) || Gaits.IsEmpty() || !Speeds || Speeds->Num() != 4 || !Stamina || !Wind ||
        Wind->Num() != 4 || !Int(*Stamina, TEXT("max"), Max) || Max != 100 ||
        !Int(*Stamina, TEXT("lockout"), M.Rules.LockoutBelow) || !Int(*Stamina, TEXT("recover"), M.Rules.RecoverAt) ||
        !Arcs || !WeaponMask(Rows(O, TEXT("weapons")), M.Rules.WeaponsMask) ||
        !Strings(Rows(O, TEXT("spooks")), M.Spooks) || !O.TryGetBoolField(TEXT("dismount"), M.bDismount) ||
        !O.TryGetBoolField(TEXT("auto_steer"), M.bAutoSteer) || !Int(O, TEXT("until_phase"), M.UntilPhase) ||
        M.UntilPhase < 0 || M.UntilPhase >= FMath::Max(1, Task.PhaseCount) || !SpaceVector(O.TryGetField(TEXT("at")), 3, Place))
        return false;
    M.Horse = FName(*Horse); M.Coat = FName(*Coat); M.At = FVector2D(Place[0], Place[1]);
    M.Rules.MaxGait = EGait::Walk;
    for (const FString& Name : Gaits)
    {
        EGait Allowed = EGait::Walk;
        if (!SpaceGait(Name, Allowed)) return false;
        if (Index(Allowed) > Index(M.Rules.MaxGait)) M.Rules.MaxGait = Allowed;
    }
    M.Rules.SpeedCmS[0] = 0;
    for (int32 Slot = 0; Slot < 4; ++Slot)
    {
        double Speed = 0, PerS = 0;
        if (!SpaceNumber((*Speeds)[Slot], Speed) || !SpaceNumber((*Wind)[Slot], PerS)) return false;
        M.Rules.SpeedCmS[Slot + 1] = static_cast<int>(Speed);
        M.Rules.StaminaPerS[Slot + 1] = static_cast<int>(PerS);
    }
    // A halted horse breathes as she does at a walk.
    M.Rules.StaminaPerS[0] = M.Rules.StaminaPerS[1];
    for (int32 Slot = 0; Slot < 3; ++Slot)
    {
        const int32 Weapon = ArcWeapons[Slot];
        const TSharedPtr<FJsonValue> Arc = Arcs->TryGetField(FString::FromInt(Weapon));
        const bool bArmed = (M.Rules.WeaponsMask & (1u << Weapon)) != 0u;
        double Range[2] = {};
        if (bArmed != Arc.IsValid() || (bArmed && !SpaceVector(Arc, 2, Range))) return false;
        M.Rules.ArcMin[Slot] = static_cast<int>(Range[0]); M.Rules.ArcMax[Slot] = static_cast<int>(Range[1]);
    }
    if (Arcs->Values.Num() != FMath::CountBits(M.Rules.WeaponsMask)) return false;
    if (!IsNull(O, TEXT("fear")))
    {
        const TSharedPtr<FJsonObject> Fear = Child(O, TEXT("fear"));
        if (!Fear || !Int(*Fear, TEXT("radius_cm"), M.FearRadiusCm) || M.FearRadiusCm <= 0 ||
            !Int(*Fear, TEXT("recover_ms"), M.Rules.FearRecoverMs) || M.Rules.FearRecoverMs <= 0)
            return false;
    }
    if (!HorseValid(M.Rules)) return false;
    const FJsonRows* TackRows = Rows(O, TEXT("tack"));
    const FJsonRows* CapRows = Rows(O, TEXT("gait_caps"));
    const FJsonRows* ForcedRows = Rows(O, TEXT("forced"));
    const FJsonRows* PackRows = Rows(O, TEXT("pack"));
    if (!TackRows || !CapRows || !ForcedRows || !PackRows || (!TackRows->IsEmpty() && M.bMounted)) return false;
    for (const auto& Row : *TackRows)
    {
        const auto T = Row.IsValid() ? Row->AsObject() : nullptr;
        FSoraTackStep Step; FString Part;
        if (!T || !Str(*T, TEXT("id"), Step.Id) || !Str(*T, TEXT("part"), Part) || !Int(*T, TEXT("refusals"), Step.Refusals) ||
            Step.Refusals < 0 || !Nullable(*T, TEXT("gift"), Step.Gift) || (Step.Refusals > 0) == Step.Gift.IsEmpty())
            return false;
        Step.Part = FName(*Part);
        M.Tack.Add(MoveTemp(Step));
    }
    for (const auto& Row : *CapRows)
    {
        const auto C = Row.IsValid() ? Row->AsObject() : nullptr;
        FSoraGaitCap Cap; FString Name;
        if (!C || !Int(*C, TEXT("from_cm"), Cap.FromCm) || !Int(*C, TEXT("to_cm"), Cap.ToCm) || Cap.FromCm < 0 ||
            Cap.ToCm <= Cap.FromCm || !Str(*C, TEXT("gait"), Name) || !SpaceGait(Name, Cap.Gait))
            return false;
        M.Caps.Add(Cap);
    }
    for (const auto& Row : *ForcedRows)
    {
        const auto F = Row.IsValid() ? Row->AsObject() : nullptr;
        FSoraForcedGait Forced; FString Name;
        if (!F || !Str(*F, TEXT("volume"), Forced.Volume) || !Str(*F, TEXT("gait"), Name) || !SpaceGait(Name, Forced.Gait)) return false;
        M.Forced.Add(MoveTemp(Forced));
    }
    for (const auto& Row : *PackRows)
    {
        const auto P = Row.IsValid() ? Row->AsObject() : nullptr;
        FSoraPackHorse Pack; FString Follow;
        int32 Hp = 0;
        if (!P || !Str(*P, TEXT("id"), Pack.Id) || !Str(*P, TEXT("follow"), Follow) ||
            (Follow != TEXT("convoy") && Follow != TEXT("lead")) || !Int(*P, TEXT("speed_cm_s"), Pack.SpeedCmS) ||
            !Int(*P, TEXT("spacing_cm"), Pack.SpacingCm) || Pack.SpacingCm <= 0 || !Int(*P, TEXT("hp"), Hp) || Hp < 0 ||
            (Follow == TEXT("convoy") && (Pack.SpeedCmS <= 0 || Hp <= 0)))
            return false;
        Pack.Follow = FName(*Follow);
        Pack.Hp = Hp;
        M.Pack.Add(MoveTemp(Pack));
    }
    return true;
}
// An area on the floor: {center, size}.
bool SpaceArea(const FJsonObject& O, FSoraVolume& Out)
{
    return SpaceVolume(O, Out, false);
}
bool SpaceAreas(const FJsonRows* Values, TArray<FSoraVolume>& Out)
{
    if (!Values) return false;
    for (const auto& Value : *Values)
    {
        const auto A = Value.IsValid() ? Value->AsObject() : nullptr;
        FSoraVolume Area;
        if (!A || !SpaceArea(*A, Area)) return false;
        Out.Add(MoveTemp(Area));
    }
    return true;
}
bool SpaceBool(const FJsonObject& O, const TCHAR* Key, bool& Out)
{
    return O.TryGetBoolField(Key, Out);
}
// A list of whole numbers.
bool SpaceInts(const FJsonRows* Values, TArray<int32>& Out)
{
    if (!Values) return false;
    for (const auto& Value : *Values)
    {
        double Number = 0; int32 Whole32 = 0;
        if (!Value.IsValid() || !Value->TryGetNumber(Number) || !Whole(Number, Whole32)) return false;
        Out.Add(Whole32);
    }
    return true;
}
// One companion: an escorted party member or an ally.
bool SpaceCompanion(const FJsonObject& O, bool bParty, FSoraCompanionSpec& C)
{
    using namespace SoraFieldcraftRules;
    FCompanionRules& R = C.Rules;
    int32 Health = 0, Revive = 0;
    if (!Str(O, TEXT("id"), C.Id) || !Int(O, TEXT("health"), Health) || !Int(O, TEXT("revive_ms"), Revive)) return false;
    R.Health = Health; R.ReviveMs = Revive;
    if (bParty)
    {
        int32 Bleedout = 0, Lance = 0, Free = 0;
        if (!Int(O, TEXT("bleedout_ms"), Bleedout) || !Int(O, TEXT("lance_ms"), Lance) || !Int(O, TEXT("free_ms"), Free) ||
            !Int(O, TEXT("release"), C.Release) || C.Release < INDEX_NONE)
            return false;
        C.Role = TEXT("escort");
        R.Downable = true; R.BleedoutMs = Bleedout; R.LanceReviveMs = Lance; R.Bound = Free > 0; R.FreeMs = Free;
        return RulesValid(R) && (C.Release == INDEX_NONE || R.Bound);
    }
    static const TSet<FName> Roles = {TEXT("fighter"), TEXT("shooter"), TEXT("rank"), TEXT("guide"), TEXT("bystander")};
    FString Role;
    bool bDownable = false;
    if (!Str(O, TEXT("role"), Role) || !Roles.Contains(FName(*Role)) || !Int(O, TEXT("weapon"), C.WeaponId) ||
        !Int(O, TEXT("rank"), C.Rank) || C.Rank < INDEX_NONE || C.Rank >= MaxRanks || (Role == TEXT("rank")) != (C.Rank >= 0) ||
        C.WeaponId < INDEX_NONE || C.WeaponId >= SoraBeatRules::WeaponCount || !SpaceBool(O, TEXT("downable"), bDownable) ||
        !SpaceBool(O, TEXT("detectable"), C.bDetectable) || !SpacePoint(O.TryGetField(TEXT("at")), C.At) ||
        !Nullable(O, TEXT("joins"), C.Joins) || (!C.Joins.IsEmpty() && !C.Joins.StartsWith(TEXT("wave_start:"))))
        return false;
    C.Role = FName(*Role);
    R.Downable = bDownable; R.BleedoutMs = 0; R.LanceReviveMs = 0; R.Bound = false; R.FreeMs = 0;
    const bool bArmed = C.Role == TEXT("fighter") || C.Role == TEXT("shooter") || C.Role == TEXT("rank");
    return RulesValid(R) && bArmed == (C.WeaponId != INDEX_NONE);
}
// Alarm lecterns, seizure nets, searchlights, the bell, cook-fires, ladders
// and the League's charge (campaign_fieldcraft.py).
bool SpaceReadFieldcraftSets(const FJsonObject& O, const FSoraBeat& Beat, FSoraFieldcraft& F)
{
    using namespace SoraFieldcraftRules;
    const FJsonRows* AlarmRows = Rows(O, TEXT("alarms"));
    const FJsonRows* LightRows = Rows(O, TEXT("searchlights"));
    const FJsonRows* LadderRows = Rows(O, TEXT("ladders"));
    if (!AlarmRows || !LightRows || !LadderRows || !O.HasField(TEXT("nets")) || !O.HasField(TEXT("bell")) ||
        !O.HasField(TEXT("fires")) || !O.HasField(TEXT("charge")))
        return false;
    for (const auto& Row : *AlarmRows)
    {
        const auto A = Row.IsValid() ? Row->AsObject() : nullptr;
        FSoraAlarmPoint Alarm;
        if (!A || !Str(*A, TEXT("id"), Alarm.Id) || !SpacePoint(A->TryGetField(TEXT("at")), Alarm.At)) return false;
        F.Alarms.Add(MoveTemp(Alarm));
    }
    F.bNets = !IsNull(O, TEXT("nets"));
    if (F.bNets)
    {
        const TSharedPtr<FJsonObject> N = Child(O, TEXT("nets"));
        FSoraNets& Nets = F.Nets;
        const FJsonRows* QuarryRows = N ? Rows(*N, TEXT("quarry")) : nullptr;
        bool bTether = false;
        if (!N || !QuarryRows || QuarryRows->IsEmpty() || !Int(*N, TEXT("windup_ms"), Nets.Rules.WindupMs) ||
            !Int(*N, TEXT("haul_ms"), Nets.Rules.HaulMs) || !Int(*N, TEXT("cut_ms"), Nets.Rules.CutMs) || !NetValid(Nets.Rules) ||
            !Int(*N, TEXT("saddle_weapon"), Nets.SaddleWeapon) || !Int(*N, TEXT("saddle_side"), Nets.SaddleSide) ||
            Nets.SaddleSide < -1 || Nets.SaddleSide > 1 || (Nets.SaddleWeapon == INDEX_NONE) != (Nets.SaddleSide == 0) ||
            !SpaceBool(*N, TEXT("tether"), bTether) || !bTether || !SpaceBool(*N, TEXT("halts"), Nets.bHalts) ||
            !SpaceInts(Rows(*N, TEXT("net_waves")), Nets.NetWaves) || !SpaceInts(Rows(*N, TEXT("nets_per_wave")), Nets.NetsPerWave) ||
            Nets.NetsPerWave.Num() != Nets.NetWaves.Num() || Nets.NetsPerWave.ContainsByPredicate([](int32 Count) { return Count < 1; }) ||
            !SpaceInts(Rows(*N, TEXT("scout_waves")), Nets.ScoutWaves) || !Int(*N, TEXT("cross_wave"), Nets.CrossWave) ||
            !Int(*N, TEXT("cross_at_cm"), Nets.CrossAtCm) || (Nets.CrossWave == INDEX_NONE) != (Nets.CrossAtCm == 0) ||
            (Nets.CrossWave != INDEX_NONE && (!Nets.NetWaves.Contains(Nets.CrossWave) || Nets.CrossAtCm < 0)) ||
            !Nullable(*N, TEXT("lost_event"), Nets.LostEvent))
            return false;
        static const TMap<FString, FSoraNets::EKind> Kinds = {
            {TEXT("pack_horse"), FSoraNets::EKind::PackHorse}, {TEXT("cart"), FSoraNets::EKind::Cart}, {TEXT("person"), FSoraNets::EKind::Person}};
        for (int32 Index = 0; Index < QuarryRows->Num(); ++Index)
        {
            const auto Q = (*QuarryRows)[Index].IsValid() ? (*QuarryRows)[Index]->AsObject() : nullptr;
            FSoraNetQuarry Quarry; FSoraNets::EKind Kind = FSoraNets::EKind::Person;
            if (!Q || !Str(*Q, TEXT("id"), Quarry.Id) || !Named(*Q, TEXT("kind"), Kinds, Kind) || (Index > 0 && Kind != Nets.Kind) ||
                !Int(*Q, TEXT("index"), Quarry.Index) || Quarry.Index != Index || !Int(*Q, TEXT("hp"), Quarry.Hp) || Quarry.Hp < 0 ||
                (Kind == FSoraNets::EKind::Person) != (Quarry.Hp == 0) ||
                (Kind == FSoraNets::EKind::Person && (Quarry.Index >= Beat.Task.TargetCount || Beat.Targets[Quarry.Index] != Quarry.Id)))
                return false;
            Nets.Kind = Kind;
            Nets.Quarry.Add(MoveTemp(Quarry));
        }
        for (const int32 Wave : Nets.NetWaves)
            if (Wave < 0 || Wave >= Beat.Task.WaveCount || Nets.ScoutWaves.Contains(Wave)) return false;
        for (const int32 Wave : Nets.ScoutWaves)
            if (Wave < 0 || Wave >= Beat.Task.WaveCount) return false;
        // A convoy's pack horses are the ride's own.
        if (Nets.Kind == FSoraNets::EKind::PackHorse &&
            (!Beat.Space.bMount || Beat.Space.Mount.Pack.Num() != Nets.Quarry.Num() || Nets.Rules.HaulMs <= 0 ||
             Nets.Quarry.ContainsByPredicate([&](const FSoraNetQuarry& Row)
                 { return Beat.Space.Mount.Pack[Row.Index].Id != Row.Id || Beat.Space.Mount.Pack[Row.Index].Hp != Row.Hp; })))
            return false;
        // An escort's net falls on its one cart; a defence's on its people.
        if ((Nets.Kind == FSoraNets::EKind::Cart && (Beat.Task.Goal != SoraBeatRules::EGoal::Escort || Nets.Quarry.Num() != 1)) ||
            (Nets.Kind == FSoraNets::EKind::Person && Beat.Task.Task != SoraBeatRules::ETask::Defend))
            return false;
    }
    for (const auto& Row : *LightRows)
    {
        const auto L = Row.IsValid() ? Row->AsObject() : nullptr;
        FSoraSearchlight Light; FSearchlightRules& R = Light.Rules;
        int32 Height = 0, Yaw = 0, Reach = 0;
        if (!L || !Str(*L, TEXT("id"), Light.Id) || !SpacePoint(L->TryGetField(TEXT("at")), Light.At) ||
            !Int(*L, TEXT("height_cm"), Height) || !Int(*L, TEXT("yaw"), Yaw) || !Int(*L, TEXT("reach_cm"), Reach) ||
            !Int(*L, TEXT("road_from_cm"), Light.RoadFromCm) || !Int(*L, TEXT("road_to_cm"), Light.RoadToCm) ||
            !Int(*L, TEXT("sweep_deg"), R.SweepDeg) || !Int(*L, TEXT("period_ms"), R.PeriodMs) || !Int(*L, TEXT("spot_cm"), R.SpotCm) ||
            !Int(*L, TEXT("suspicious_ms"), R.SuspiciousMs) || !Int(*L, TEXT("alert_ms"), R.AlertMs) || !Int(*L, TEXT("lock_ms"), R.LockMs) ||
            !Nullable(*L, TEXT("active_on"), Light.ActiveOn) || !SpaceBool(*L, TEXT("spooks"), Light.bSpooks))
            return false;
        Light.HeightCm = static_cast<float>(Height); Light.Yaw = static_cast<float>(Yaw); Light.ReachCm = static_cast<float>(Reach);
        // A road's light sweeps its stretch and frightens horses; a wall's sweeps its arc for the guards.
        const bool bValid = Light.IsRoad()
            ? Light.RoadFromCm >= 0 && Light.RoadFromCm < Light.RoadToCm && Light.bSpooks && !Light.ActiveOn.IsEmpty() &&
                R.PeriodMs >= 2 && R.SpotCm > 0 && Beat.Space.bRoute
            : SearchlightValid(R) && Height > 0 && Reach > 0 && !Light.bSpooks;
        if (!bValid) return false;
        F.Searchlights.Add(MoveTemp(Light));
    }
    F.bBell = !IsNull(O, TEXT("bell"));
    if (F.bBell)
    {
        const TSharedPtr<FJsonObject> B = Child(O, TEXT("bell"));
        int32 Height = 0;
        if (!B || !Str(*B, TEXT("id"), F.Bell.Id) || !SpacePoint(B->TryGetField(TEXT("at")), F.Bell.At) ||
            !Int(*B, TEXT("height_cm"), Height) || Height <= 0 || !Int(*B, TEXT("radius_cm"), F.Bell.Rules.RadiusCm) ||
            F.Bell.Rules.RadiusCm <= 0 || !Int(*B, TEXT("uses"), F.Bell.Rules.Uses) || F.Bell.Rules.Uses <= 0 ||
            !Int(*B, TEXT("hold_ms"), F.Bell.Rules.HoldMs) || F.Bell.Rules.HoldMs <= 0)
            return false;
        F.Bell.HeightCm = static_cast<float>(Height);
    }
    F.bFires = !IsNull(O, TEXT("fires"));
    if (F.bFires)
    {
        const TSharedPtr<FJsonObject> C = Child(O, TEXT("fires"));
        const FJsonRows* PointRows = C ? Rows(*C, TEXT("points")) : nullptr;
        if (!C || !PointRows || PointRows->IsEmpty() || !SpaceInts(Rows(*C, TEXT("out_at")), F.Fires.OutAt) ||
            !Int(*C, TEXT("relight_ms"), F.Fires.RelightMs) || F.Fires.RelightMs <= 0 || Beat.Task.Goal != SoraBeatRules::EGoal::Hold)
            return false;
        for (int32 Mark = 0; Mark < F.Fires.OutAt.Num(); ++Mark)
            if (F.Fires.OutAt[Mark] <= 0 || F.Fires.OutAt[Mark] >= 1000 || (Mark > 0 && F.Fires.OutAt[Mark] <= F.Fires.OutAt[Mark - 1]))
                return false;
        for (const auto& Row : *PointRows)
        {
            const auto P = Row.IsValid() ? Row->AsObject() : nullptr;
            FString Id; FVector2D At;
            if (!P || !Str(*P, TEXT("id"), Id) || !SpacePoint(P->TryGetField(TEXT("at")), At)) return false;
            F.Fires.Ids.Add(Id); F.Fires.Points.Add(At);
        }
    }
    for (const auto& Row : *LadderRows)
    {
        const auto L = Row.IsValid() ? Row->AsObject() : nullptr;
        FSoraLadder Ladder; int32 Yaw = 0, Height = 0;
        const TSharedPtr<FJsonObject> Roof = L ? Child(*L, TEXT("roof")) : nullptr;
        if (!L || !Roof || !Str(*L, TEXT("id"), Ladder.Id) || !SpacePoint(L->TryGetField(TEXT("foot")), Ladder.Foot) ||
            !Int(*L, TEXT("yaw"), Yaw) || !SpaceArea(*Roof, Ladder.Roof) || !Int(*L, TEXT("height_cm"), Height) || Height <= 0 ||
            !Int(*L, TEXT("drop_noise_cm"), Ladder.DropNoiseCm) || Ladder.DropNoiseCm <= 0 ||
            Ladder.DropNoiseCm > 10 * SoraStealthRules::NoiseRadiusCm(SoraStealthRules::ENoise::Landing) || !L->HasField(TEXT("straw")) ||
            !SpaceInts(Rows(*L, TEXT("guards")), Ladder.Guards))
            return false;
        Ladder.bStraw = !IsNull(*L, TEXT("straw"));
        if (Ladder.bStraw)
        {
            const TSharedPtr<FJsonObject> Straw = Child(*L, TEXT("straw"));
            if (!Straw || !SpaceArea(*Straw, Ladder.Straw)) return false;
        }
        for (const int32 Guard : Ladder.Guards)
            if (Guard < 0 || Guard >= Beat.Guards.Num()) return false;
        Ladder.Yaw = static_cast<float>(Yaw); Ladder.HeightCm = static_cast<float>(Height);
        F.Ladders.Add(MoveTemp(Ladder));
    }
    F.bCharge = !IsNull(O, TEXT("charge"));
    if (F.bCharge)
    {
        const TSharedPtr<FJsonObject> C = Child(O, TEXT("charge"));
        const FJsonRows* StakeRows = C ? Rows(*C, TEXT("stakes")) : nullptr;
        FSoraCharge& Charge = F.Charge;
        if (!C || !StakeRows || !Int(*C, TEXT("riders"), Charge.Riders) || Charge.Riders <= 0 || !Str(*C, TEXT("rival"), Charge.Rival) ||
            !Int(*C, TEXT("pace_cm_s"), Charge.PaceCmS) || !Int(*C, TEXT("catch_up_cm_s"), Charge.CatchUpCmS) ||
            Charge.CatchUpCmS <= 0 || Charge.CatchUpCmS >= Charge.PaceCmS || !Int(*C, TEXT("stake_break_ms"), Charge.StakeBreakMs) ||
            Charge.StakeBreakMs <= 0 || !Beat.Space.bRoute || !Beat.Space.bMount)
            return false;
        for (const auto& Row : *StakeRows)
        {
            const auto S = Row.IsValid() ? Row->AsObject() : nullptr;
            FString Id; FVector2D At;
            if (!S || !Str(*S, TEXT("id"), Id) || !SpacePoint(S->TryGetField(TEXT("at")), At)) return false;
            Charge.StakeIds.Add(Id); Charge.Stakes.Add(At);
        }
    }
    return true;
}
// The beat's fieldcraft block (campaign_fieldcraft.py): every key present,
// with the types and ranges SoraFieldcraftRules accepts.
bool SpaceReadFieldcraft(const FJsonObject& O, const FSoraBeat& Beat, FSoraFieldcraft& F)
{
    using namespace SoraFieldcraftRules;
    const FJsonRows* LampRows = Rows(O, TEXT("lamps"));
    const FJsonRows* FloorRows = Rows(O, TEXT("surfaces"));
    const FJsonRows* PartyRows = Rows(O, TEXT("party"));
    const FJsonRows* ReleaseRows = Rows(O, TEXT("releases"));
    const FJsonRows* AllyRows = Rows(O, TEXT("allies"));
    const FJsonRows* PeopleRows = Rows(O, TEXT("people"));
    if (!LampRows || !FloorRows || !PartyRows || !ReleaseRows || !AllyRows || !PeopleRows || !SpaceBool(O, TEXT("signal"), F.bSignal) ||
        !SpacePoints(Rows(O, TEXT("hide_spots")), F.HideSpots) || F.bSignal == F.HideSpots.IsEmpty() ||
        !O.HasField(TEXT("water")) || !O.HasField(TEXT("climb")) || !O.HasField(TEXT("stones")) || !O.HasField(TEXT("candle")) ||
        !O.HasField(TEXT("volley")))
        return false;
    static const TMap<FString, FSoraLamp::ESnuff> Snuffs = {
        {TEXT("hold"), FSoraLamp::ESnuff::Hold}, {TEXT("shot"), FSoraLamp::ESnuff::Shot}, {TEXT("none"), FSoraLamp::ESnuff::None}};
    for (const auto& Row : *LampRows)
    {
        const auto L = Row.IsValid() ? Row->AsObject() : nullptr;
        FSoraLamp Lamp; FString Kind; int32 Radius = 0;
        if (!L || !Str(*L, TEXT("id"), Lamp.Id) || !Str(*L, TEXT("kind"), Kind) || !SpacePoint(L->TryGetField(TEXT("at")), Lamp.At) ||
            !Int(*L, TEXT("radius_cm"), Radius) || Radius <= 0 || !Named(*L, TEXT("snuff"), Snuffs, Lamp.Snuff) ||
            !Int(*L, TEXT("hold_ms"), Lamp.HoldMs) || !Int(*L, TEXT("relight_ms"), Lamp.RelightMs) || Lamp.RelightMs < 0 ||
            (Lamp.Snuff == FSoraLamp::ESnuff::Hold) != (Lamp.HoldMs > 0))
            return false;
        Lamp.Kind = FName(*Kind); Lamp.RadiusCm = static_cast<float>(Radius);
        F.Lamps.Add(MoveTemp(Lamp));
    }
    for (const auto& Row : *FloorRows)
    {
        const auto S = Row.IsValid() ? Row->AsObject() : nullptr;
        FSoraFloorPatch Floor; FString Kind;
        if (!S || !Str(*S, TEXT("kind"), Kind) || !SpaceArea(*S, Floor.Area) || !Int(*S, TEXT("height_cm"), Floor.HeightCm) ||
            Floor.HeightCm < 0 || !Int(*S, TEXT("step_permille"), Floor.StepPermille) ||
            !Int(*S, TEXT("crouch_permille"), Floor.CrouchPermille) || Floor.StepPermille <= 0 || Floor.StepPermille > 10000 ||
            Floor.CrouchPermille < 0 || Floor.CrouchPermille > 10000)
            return false;
        Floor.Kind = FName(*Kind);
        F.Floors.Add(MoveTemp(Floor));
    }
    F.bWater = !IsNull(O, TEXT("water"));
    if (F.bWater)
    {
        const TSharedPtr<FJsonObject> W = Child(O, TEXT("water"));
        FWaterRules& R = F.Water.Rules;
        const FJsonRows* LineRows = W ? Rows(*W, TEXT("lines")) : nullptr;
        if (!W || !SpaceArea(*W, F.Water.Area) || !Int(*W, TEXT("surface_cm_s"), R.SurfaceCmS) || !Int(*W, TEXT("dive_cm_s"), R.DiveCmS) ||
            !Int(*W, TEXT("breath_ms"), R.BreathMs) || !Int(*W, TEXT("recover_ms"), R.RecoverMs) ||
            !Int(*W, TEXT("drown_hp_s"), R.DrownHpPerSecond) || !Int(*W, TEXT("surface_step_permille"), F.Water.SurfaceStepPermille) ||
            F.Water.SurfaceStepPermille <= 0 || !WaterValid(R) || !SpaceAreas(Rows(*W, TEXT("cover")), F.Water.Cover) || !LineRows)
            return false;
        for (const auto& Row : *LineRows)
        {
            const auto A = Row.IsValid() ? Row->AsObject() : nullptr;
            FSoraVolume Line; int32 Noise = 0;
            if (!A || !SpaceArea(*A, Line) || !Int(*A, TEXT("noise_cm"), Noise) || Noise <= 0) return false;
            F.Water.Lines.Add(Line); F.Water.LineNoiseCm.Add(Noise);
        }
    }
    F.bClimb = !IsNull(O, TEXT("climb"));
    if (F.bClimb)
    {
        const TSharedPtr<FJsonObject> C = Child(O, TEXT("climb"));
        FClimbRules& R = F.Climb.Rules;
        const FJsonRows* LedgeRows = C ? Rows(*C, TEXT("ledges")) : nullptr;
        int32 Yaw = 0, Width = 0, Depth = 0;
        if (!C || !SpacePoint(C->TryGetField(TEXT("at")), F.Climb.At) || !Int(*C, TEXT("yaw"), Yaw) || !Int(*C, TEXT("width_cm"), Width) ||
            !Int(*C, TEXT("depth_cm"), Depth) || Width <= 0 || Depth <= 0 || !Int(*C, TEXT("height_cm"), R.HeightCm) ||
            !Int(*C, TEXT("holds"), R.Holds) || !Int(*C, TEXT("grip_per_hold"), R.GripPerHold) ||
            !Int(*C, TEXT("regen_per_s"), R.RegenPerSecond) || !Int(*C, TEXT("hurt_cm"), R.HurtCm) || !Int(*C, TEXT("hurt_hp"), R.HurtHp) ||
            !Int(*C, TEXT("lethal_cm"), R.LethalCm) || !LedgeRows || !Strings(Rows(*C, TEXT("ledge_events")), F.Climb.LedgeEvents) ||
            F.Climb.LedgeEvents.Num() != LedgeRows->Num() || !Nullable(*C, TEXT("top_event"), F.Climb.TopEvent))
            return false;
        R.LedgeMask = 0u;
        for (const auto& Value : *LedgeRows)
        {
            double Number = 0; int32 Hold = 0;
            if (!Value.IsValid() || !Value->TryGetNumber(Number) || !Whole(Number, Hold) || Hold <= 0 || Hold >= 32) return false;
            R.LedgeMask |= 1u << Hold;
        }
        F.Climb.Yaw = static_cast<float>(Yaw); F.Climb.WidthCm = static_cast<float>(Width); F.Climb.DepthCm = static_cast<float>(Depth);
        if (!ClimbValid(R)) return false;
    }
    F.bStones = !IsNull(O, TEXT("stones"));
    if (F.bStones)
    {
        const TSharedPtr<FJsonObject> S = Child(O, TEXT("stones"));
        if (!S || !Int(*S, TEXT("carried"), F.Stones.Carried) || !Int(*S, TEXT("max"), F.Stones.Max) || F.Stones.Max <= 0 ||
            F.Stones.Carried < 0 || F.Stones.Carried > F.Stones.Max || !Int(*S, TEXT("noise_cm"), F.Stones.NoiseCm) ||
            F.Stones.NoiseCm <= 0 || !Int(*S, TEXT("investigate_ms"), F.Stones.InvestigateMs) || F.Stones.InvestigateMs <= 0 ||
            !SpacePoints(Rows(*S, TEXT("piles")), F.Stones.Piles))
            return false;
    }
    F.bCandle = !IsNull(O, TEXT("candle"));
    if (F.bCandle)
    {
        const TSharedPtr<FJsonObject> L = Child(O, TEXT("candle"));
        FCandle& R = F.Candle;
        int32 Radius = 0;
        if (!L || !Int(*L, TEXT("visibility_permille"), R.VisibilityPermille) || !Int(*L, TEXT("cupped_permille"), R.CuppedVisibilityPermille) ||
            !Int(*L, TEXT("cupped_rate_permille"), R.CuppedRatePermille) || !Int(*L, TEXT("radius_cm"), Radius) || Radius <= 0 ||
            R.CuppedVisibilityPermille < 1000 || R.VisibilityPermille <= R.CuppedVisibilityPermille ||
            R.CuppedRatePermille <= 0 || R.CuppedRatePermille >= 1000)
            return false;
        F.CandleRadiusCm = static_cast<float>(Radius);
    }
    for (const auto& Row : *ReleaseRows)
    {
        const auto R = Row.IsValid() ? Row->AsObject() : nullptr;
        FSoraRelease Release;
        if (!R || !Str(*R, TEXT("id"), Release.Id) || !SpacePoint(R->TryGetField(TEXT("at")), Release.At) ||
            !Int(*R, TEXT("hold_ms"), Release.HoldMs) || Release.HoldMs <= 0)
            return false;
        F.Releases.Add(MoveTemp(Release));
    }
    TSet<FString> Ids;
    for (const auto& Row : *PartyRows)
    {
        const auto M = Row.IsValid() ? Row->AsObject() : nullptr;
        FSoraCompanionSpec Member;
        bool bSeen = false;
        if (!M || !SpaceCompanion(*M, true, Member) || Member.Release >= F.Releases.Num() ||
            (Member.Release >= 0 && Member.Rules.FreeMs != F.Releases[Member.Release].HoldMs))
            return false;
        Ids.Add(Member.Id, &bSeen);
        if (bSeen) return false;
        F.Party.Add(MoveTemp(Member));
    }
    for (const auto& Row : *AllyRows)
    {
        const auto A = Row.IsValid() ? Row->AsObject() : nullptr;
        FSoraCompanionSpec Ally;
        bool bSeen = false;
        if (!A || !SpaceCompanion(*A, false, Ally)) return false;
        Ids.Add(Ally.Id, &bSeen);
        if (bSeen) return false;
        F.Allies.Add(MoveTemp(Ally));
    }
    for (const auto& Row : *PeopleRows)
    {
        const auto P = Row.IsValid() ? Row->AsObject() : nullptr;
        FSoraDefendedPerson Person;
        bool bSeen = false;
        if (!P || !Str(*P, TEXT("id"), Person.Id) || !Int(*P, TEXT("target"), Person.Target) || Person.Target < 0 ||
            Person.Target >= Beat.Task.TargetCount || !SpacePoint(P->TryGetField(TEXT("at")), Person.At) ||
            Person.At != Beat.Space.Targets[Person.Target])
            return false;
        Ids.Add(Person.Id, &bSeen);
        if (bSeen) return false;
        F.People.Add(MoveTemp(Person));
    }
    // Volley ranks: each a full row of gunners with the volley's arm, from the start.
    F.bVolley = !IsNull(O, TEXT("volley"));
    TArray<int32> Gunners;
    Gunners.Init(0, MaxRanks);
    for (const FSoraCompanionSpec& Ally : F.Allies)
        if (Ally.Rank >= 0)
        {
            if (!F.bVolley || !Ally.Joins.IsEmpty()) return false;
            ++Gunners[Ally.Rank];
        }
    if (F.bVolley)
    {
        const TSharedPtr<FJsonObject> V = Child(O, TEXT("volley"));
        FVolleyRules& R = F.Volley.Rules;
        if (!V || !Int(*V, TEXT("ranks"), R.Ranks) || !Int(*V, TEXT("per_rank"), F.Volley.PerRank) || F.Volley.PerRank <= 0 ||
            !Int(*V, TEXT("weapon"), F.Volley.WeaponId) || F.Volley.WeaponId < 0 || F.Volley.WeaponId >= SoraBeatRules::WeaponCount ||
            !Int(*V, TEXT("order_delay_ms"), R.OrderDelayMs) || !Int(*V, TEXT("cycle_ms"), R.CycleMs) ||
            !Int(*V, TEXT("radius_cm"), R.RadiusCm) || !Int(*V, TEXT("range_cm"), R.RangeCm) || !VolleyValid(R) ||
            !Int(*V, TEXT("smoke_ms"), F.Volley.SmokeMs) || F.Volley.SmokeMs < 0 || !SpaceBool(*V, TEXT("auto_order"), F.Volley.bAutoOrder))
            return false;
        for (int32 Rank = 0; Rank < MaxRanks; ++Rank)
            if (Gunners[Rank] != (Rank < R.Ranks ? F.Volley.PerRank : 0)) return false;
        for (const FSoraCompanionSpec& Ally : F.Allies)
            if (Ally.Rank >= 0 && Ally.WeaponId != F.Volley.WeaponId) return false;
    }
    // Only an escort walks a party, and only its road holds hide spots and cell doors.
    const bool bEscort = Beat.Task.Goal == SoraBeatRules::EGoal::Escort;
    return F.Party.IsEmpty() != bEscort && (bEscort || (!F.bSignal && F.Releases.IsEmpty())) &&
        SpaceReadFieldcraftSets(O, Beat, F);
}
}

FVector2D FSoraZone::PointAlong(float Chainage) const
{
    if (Route.IsEmpty()) return Rect.GetCenter();
    float Remaining = FMath::Max(0.f, Chainage);
    for (int32 Index = 1; Index < Route.Num(); ++Index)
    {
        const float Segment = FVector2D::Distance(Route[Index - 1], Route[Index]);
        if (Remaining <= Segment && Segment > 0.f) return FMath::Lerp(Route[Index - 1], Route[Index], Remaining / Segment);
        Remaining -= Segment;
    }
    return Route.Last();
}
float FSoraZone::ChainageOf(const FVector2D& Point) const
{
    float Best = 0.f, BestDistance = MAX_flt, Walked = 0.f;
    for (int32 Index = 1; Index < Route.Num(); ++Index)
    {
        const FVector2D A = Route[Index - 1], B = Route[Index];
        const float Segment = FVector2D::Distance(A, B);
        const float Share = Segment > 0.f ? FMath::Clamp(FVector2D::DotProduct(Point - A, B - A) / (Segment * Segment), 0.f, 1.f) : 0.f;
        const float Distance = FVector2D::Distance(Point, A + (B - A) * Share);
        if (Distance < BestDistance) { BestDistance = Distance; Best = Walked + Segment * Share; }
        Walked += Segment;
    }
    return Best;
}
float FSoraZone::HeadingAt(float Chainage) const
{
    float Remaining = FMath::Max(0.f, Chainage);
    for (int32 Index = 1; Index < Route.Num(); ++Index)
    {
        const float Segment = FVector2D::Distance(Route[Index - 1], Route[Index]);
        if (Remaining <= Segment || Index == Route.Num() - 1)
            return FMath::RadiansToDegrees(FMath::Atan2(Route[Index].Y - Route[Index - 1].Y, Route[Index].X - Route[Index - 1].X));
        Remaining -= Segment;
    }
    return 0.f;
}
int32 FSoraSpace::ZoneAt(const FVector& Location) const
{
    for (int32 Index = 0; Index < Zones.Num(); ++Index)
        if (Zones[Index].Contains(Location)) return Index;
    // The arena's floor inside its perimeter walls (SoraWorldBuilder.cpp).
    return Hub != INDEX_NONE && FMath::Abs(Location.X) <= 3150.f && FMath::Abs(Location.Y) <= 2550.f ? INDEX_NONE : -2;
}

bool FSoraCatalog::LoadSpace(const FJsonObject& Data, FSoraChapter& C)
{
    auto Bad = [&](const FString& What) { return Fail(FString::Printf(TEXT("%s space: %s"), *C.Id, *What)); };
    FSoraSpace& S = C.Space;
    static const TSet<FName> Styles = {TEXT("estate"), TEXT("ward"), TEXT("foundry"), TEXT("citadel")};
    static const TSet<FName> Forms = {TEXT("hall"), TEXT("yard"), TEXT("field"), TEXT("route")};
    if (!IsNull(Data, TEXT("hub")) && (!Int(Data, TEXT("hub"), S.Hub) || S.Hub != C.Map)) return Bad(TEXT("the hub is not the chapter's arena"));
    if (!SpacePose(Data, TEXT("start"), S.Start, S.StartYaw)) return Bad(TEXT("no start"));
    const FJsonRows* ZoneRows = Rows(Data, TEXT("zones"));
    if (!ZoneRows) return Bad(TEXT("no zones"));
    for (const auto& Row : *ZoneRows)
    {
        const auto O = Row.IsValid() ? Row->AsObject() : nullptr;
        FSoraZone Zone; FString Style, Form; int32 Wall = 0;
        double Rect[4] = {};
        if (!O || !Str(*O, TEXT("id"), Zone.Id) || !Str(*O, TEXT("place"), Zone.Place) || !Str(*O, TEXT("style"), Style) ||
            !Str(*O, TEXT("form"), Form) || !Styles.Contains(FName(*Style)) || !Forms.Contains(FName(*Form)) ||
            !SpaceVector(O->TryGetField(TEXT("rect")), 4, Rect) || Rect[0] >= Rect[2] || Rect[1] >= Rect[3] ||
            !Int(*O, TEXT("wall_cm"), Wall) || Wall <= 0 || !SpacePose(*O, TEXT("entry"), Zone.Entry, Zone.EntryYaw) ||
            !SpaceBoxes(Rows(*O, TEXT("walls")), Zone.Walls) || Zone.Walls.Num() != 4 ||
            !SpaceBoxes(Rows(*O, TEXT("cover")), Zone.Cover) || !SpacePoints(Rows(*O, TEXT("route")), Zone.Route) ||
            (Form == TEXT("route")) != (Zone.Route.Num() >= 2) || (Zone.Route.Num() == 1))
            return Bad(FString::Printf(TEXT("invalid zone %d"), S.Zones.Num()));
        Zone.Style = FName(*Style); Zone.Form = FName(*Form); Zone.WallHeight = static_cast<float>(Wall);
        Zone.Rect = FBox2D(FVector2D(Rect[0], Rect[1]), FVector2D(Rect[2], Rect[3]));
        if (!Zone.Rect.IsInside(Zone.Entry)) return Bad(Zone.Id + TEXT(" entry is outside its floor"));
        for (int32 Index = 1; Index < Zone.Route.Num(); ++Index) Zone.RouteLength += FVector2D::Distance(Zone.Route[Index - 1], Zone.Route[Index]);
        const FJsonRows* PropRows = Rows(*O, TEXT("props"));
        if (!PropRows) return Bad(Zone.Id + TEXT(" has no props list"));
        for (const auto& PropRow : *PropRows)
        {
            const auto P = PropRow.IsValid() ? PropRow->AsObject() : nullptr;
            FSoraProp Prop; FString Mesh; FVector2D At; float Yaw = 0.f;
            if (!P || !Str(*P, TEXT("mesh"), Mesh) || !SpacePose(*P, TEXT("at"), At, Yaw)) return Bad(Zone.Id + TEXT(" has an invalid prop"));
            Prop.Mesh = FName(*Mesh); Prop.At = At; Prop.Yaw = Yaw;
            Zone.Props.Add(Prop);
        }
        S.Zones.Add(MoveTemp(Zone));
    }
    if (!SpacePoints(Rows(Data, TEXT("sites")), S.Sites) || S.Sites.Num() != SoraBeatRules::SiteCount) return Bad(TEXT("needs three sites"));
    const FJsonRows* BeatRows = Rows(Data, TEXT("beats"));
    if (!BeatRows || BeatRows->Num() != C.Beats.Num()) return Bad(TEXT("needs one space per beat"));
    const auto ZoneIndex = [&](int32 Zone) { return Zone == INDEX_NONE ? S.Hub != INDEX_NONE : S.Zones.IsValidIndex(Zone); };
    for (int32 BeatIndex = 0; BeatIndex < C.Beats.Num(); ++BeatIndex)
    {
        FSoraBeat& Beat = C.Beats[BeatIndex];
        FSoraBeatSpace& B = Beat.Space;
        const SoraBeatRules::FTask& Task = Beat.Task;
        const auto O = (*BeatRows)[BeatIndex].IsValid() ? (*BeatRows)[BeatIndex]->AsObject() : nullptr;
        const TSharedPtr<FJsonObject> Exit = O ? Child(*O, TEXT("exit")) : nullptr;
        const TSharedPtr<FJsonObject> Kit = O ? Child(*O, TEXT("kit")) : nullptr;
        const FJsonRows* PatrolRows = O ? Rows(*O, TEXT("patrols")) : nullptr;
        const FJsonRows* VolumeRows = O ? Rows(*O, TEXT("volumes")) : nullptr;
        const FJsonRows* StationRows = O ? Rows(*O, TEXT("step_stations")) : nullptr;
        FString Id;
        if (!O || !Str(*O, TEXT("beat"), Id) || Id != Beat.Id || !Int(*O, TEXT("zone"), B.Zone) || !ZoneIndex(B.Zone) ||
            !SpacePose(*O, TEXT("entry"), B.Entry, B.EntryYaw) || !SpacePoint(O->TryGetField(TEXT("anchor")), B.Anchor) ||
            !SpacePoints(Rows(*O, TEXT("objectives")), B.Objectives) || !SpacePoints(Rows(*O, TEXT("pickups")), B.Pickups) ||
            !SpacePoints(Rows(*O, TEXT("dropoffs")), B.Dropoffs) || !SpacePoints(Rows(*O, TEXT("targets")), B.Targets) ||
            !SpacePoints(Rows(*O, TEXT("stations")), B.Stations) || !SpacePoints(Rows(*O, TEXT("spawns")), B.Spawns) ||
            !Exit || !SpaceVolume(*Exit, B.Exit, false) || !Kit || !PatrolRows || !VolumeRows || !StationRows)
            return Bad(FString::Printf(TEXT("beat %s lacks a required field"), *Beat.Id));
        const auto Recovery = O->TryGetField(TEXT("recovery"));
        if (!Recovery.IsValid() || (Task.RecoveryWeapons != 0u) != (Recovery->Type != EJson::Null) ||
            (Task.RecoveryWeapons != 0u && (!SpacePoint(Recovery,B.Recovery) || B.Zone < 0 ||
                !S.Zones[B.Zone].Rect.IsInside(B.Recovery + FVector2D(350,350)) ||
                !S.Zones[B.Zone].Rect.IsInside(B.Recovery - FVector2D(350,350))))) return Bad(Beat.Id + TEXT(" recovery well"));
        if (B.Objectives.Num() != Beat.Objectives.Num() || B.Pickups.Num() != Task.Pickups || B.Dropoffs.Num() != Task.Dropoffs ||
            B.Targets.Num() != Task.TargetCount || StationRows->Num() != Task.StepCount || (Task.StepCount > 0) == B.Stations.IsEmpty())
            return Bad(FString::Printf(TEXT("beat %s places other points than its task has"), *Beat.Id));
        for (const auto& Value : *StationRows)
        {
            double Station = 0;
            if (!SpaceNumber(Value, Station) || !B.Stations.IsValidIndex(static_cast<int32>(Station))) return Bad(Beat.Id + TEXT(" step station"));
            B.StepStations.Add(static_cast<int32>(Station));
        }
        for (const auto& Value : *PatrolRows)
        {
            const FJsonRows* Loop = nullptr;
            TArray<FVector2D>& Points = B.Patrols.AddDefaulted_GetRef();
            if (!Value.IsValid() || !Value->TryGetArray(Loop) || !SpacePoints(Loop, Points) || Points.Num() < 2) return Bad(Beat.Id + TEXT(" patrol"));
        }
        for (const auto& Value : *VolumeRows)
        {
            const auto V = Value.IsValid() ? Value->AsObject() : nullptr;
            FSoraVolume Volume;
            if (!V || !SpaceVolume(*V, Volume, true)) return Bad(Beat.Id + TEXT(" volume"));
            B.Volumes.Add(MoveTemp(Volume));
        }
        if (!(Beat.Waves.Num() == 0 && !Beat.Is(SoraBeatRules::EType::Duel) && !Beat.Is(SoraBeatRules::EType::Boss) &&
            !Beat.Is(SoraBeatRules::EType::StealthZone)) && B.Spawns.IsEmpty())
            return Bad(Beat.Id + TEXT(" puts opponents on the field with no spawns"));
        B.bClosing = !IsNull(*O, TEXT("closing"));
        B.bCache = !IsNull(*O, TEXT("cache"));
        B.bCamera = !IsNull(*O, TEXT("camera"));
        double Camera[9] = {};
        if ((B.bClosing && !SpacePoint(O->TryGetField(TEXT("closing")), B.Closing)) ||
            (B.bCache && !SpacePoint(O->TryGetField(TEXT("cache")), B.Cache)) ||
            (B.bCamera && !SpaceVector(O->TryGetField(TEXT("camera")), 9, Camera)) ||
            B.bClosing != Task.AnchorAfterLines || B.bCache != Beat.Is(SoraBeatRules::EType::ExploreOptional) ||
            B.bCamera != Beat.Is(SoraBeatRules::EType::Cinematic))
            return Bad(Beat.Id + TEXT(" closing anchor, cache or camera"));
        B.CameraFrom = FVector(Camera[0], Camera[1], Camera[2]);
        B.CameraTo = FVector(Camera[3], Camera[4], Camera[5]);
        B.CameraLook = FVector(Camera[6], Camera[7], Camera[8]);
        B.bRoute = !IsNull(*O, TEXT("route"));
        const bool bRouted = Beat.Is(SoraBeatRules::EType::HorsebackRide) || Task.Goal == SoraBeatRules::EGoal::Escort;
        if (B.bRoute != bRouted || (B.bRoute && (!S.Zones.IsValidIndex(B.Zone) || !S.Zones[B.Zone].IsRoute())))
            return Bad(Beat.Id + TEXT(" rides and escorts run on a road"));
        if (B.bRoute)
        {
            const TSharedPtr<FJsonObject> Route = Child(*O, TEXT("route"));
            int32 RouteZone = INDEX_NONE;
            if (!Route || !Int(*Route, TEXT("zone"), RouteZone) || RouteZone != B.Zone ||
                !Int(*Route, TEXT("margin_cm"), B.RouteMarginCm) || B.RouteMarginCm < 0)
                return Bad(Beat.Id + TEXT(" route"));
            // The escorted party walks the whole road between its margins.
            if (Task.Goal == SoraBeatRules::EGoal::Escort &&
                Task.PathCm != FMath::RoundToInt32(S.Zones[B.Zone].RouteLength) - 2 * B.RouteMarginCm)
                return Bad(Beat.Id + TEXT(" escort path is not its road"));
        }
        if (!SpaceNullableName(*Kit, TEXT("work"), B.Work) || !SpaceNullableName(*Kit, TEXT("item"), B.Item) ||
            !SpaceNames(Rows(*Kit, TEXT("pickups")), B.PickupKinds) || !SpaceNames(Rows(*Kit, TEXT("dropoffs")), B.DropoffKinds) ||
            !SpaceNames(Rows(*Kit, TEXT("targets")), B.TargetKinds) || !SpaceNames(Rows(*Kit, TEXT("party")), B.Party) ||
            B.PickupKinds.Num() != Task.Pickups || B.TargetKinds.Num() != Task.TargetCount ||
            (!Beat.Is(SoraBeatRules::EType::HorsebackRide) && B.DropoffKinds.Num() != Task.Dropoffs))
            return Bad(Beat.Id + TEXT(" kit"));
        B.bMount = !IsNull(*O, TEXT("mount"));
        const TSharedPtr<FJsonObject> Mount = B.bMount ? Child(*O, TEXT("mount")) : nullptr;
        if (B.bMount != (Beat.Is(SoraBeatRules::EType::HorsebackRide) || (Mount.IsValid() && Beat.Is(SoraBeatRules::EType::Boss))) ||
            (B.bMount && (!Mount || !SpaceReadMount(*Mount, Task, B.Mount))))
            return Bad(Beat.Id + TEXT(" horse"));
        const TSharedPtr<FJsonObject> Fieldcraft = Child(*O, TEXT("fieldcraft"));
        if (!Fieldcraft || !SpaceReadFieldcraft(*Fieldcraft, Beat, B.Fieldcraft))
            return Bad(Beat.Id + TEXT(" fieldcraft"));
    }
    const FJsonRows* PickupRows = Rows(Data, TEXT("pickups"));
    if (!PickupRows) return Bad(TEXT("no pickups"));
    for (const auto& Row : *PickupRows)
    {
        const auto O = Row.IsValid() ? Row->AsObject() : nullptr;
        FSoraPickup Pickup; FString Id;
        if (!O || !Str(*O, TEXT("collectible"), Id) || !Int(*O, TEXT("zone"), Pickup.Zone) || !ZoneIndex(Pickup.Zone) ||
            !SpacePoint(O->TryGetField(TEXT("at")), Pickup.At))
            return Bad(TEXT("invalid pickup"));
        Pickup.Collectible = C.Collectibles.IndexOfByPredicate([&](const FSoraCollectible& Item) { return Item.Id == Id; });
        if (!C.Collectibles.IsValidIndex(Pickup.Collectible) || C.Collectibles[Pickup.Collectible].Pickup != INDEX_NONE)
            return Bad(FString::Printf(TEXT("pickup for %s"), *Id));
        C.Collectibles[Pickup.Collectible].Pickup = S.Pickups.Num();
        S.Pickups.Add(Pickup);
    }
    return true;
}
